import * as THREE from 'three';

const canvas=document.querySelector('#world'), scene=new THREE.Scene();
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12;
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.1,180);
scene.fog=new THREE.Fog(0x9bbbaa,35,100);
const hemi=new THREE.HemisphereLight(0xcce4ef,0x596248,1.6);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffedc4,3.2);sun.position.set(-25,40,15);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;sun.shadow.bias=-.0003;scene.add(sun);scene.add(sun.target);
const materials={grass:new THREE.MeshStandardMaterial({color:0x68884c,roughness:.96}),dirt:new THREE.MeshStandardMaterial({color:0x765d43,roughness:1}),stone:new THREE.MeshStandardMaterial({color:0x85877d,roughness:.92}),wood:new THREE.MeshStandardMaterial({color:0x765238,roughness:.92}),leaves:new THREE.MeshStandardMaterial({color:0x456944,roughness:1}),sand:new THREE.MeshStandardMaterial({color:0xb8a675,roughness:1}),plank:new THREE.MeshStandardMaterial({color:0xb38754,roughness:.8}),brick:new THREE.MeshStandardMaterial({color:0x956654,roughness:.95}),glass:new THREE.MeshStandardMaterial({color:0x86b9ae,roughness:.25,metalness:.1,transparent:true,opacity:.58}),bedrock:new THREE.MeshStandardMaterial({color:0x414948,roughness:.8})};
const palette=[['grass','Grass','▧'],['dirt','Dirt','▪'],['stone','Stone','◩'],['wood','Wood','▥'],['leaves','Leaves','✿'],['plank','Planks','▤'],['brick','Brick','▦'],['sand','Sand','◧']];
const blockGeo=new THREE.BoxGeometry(1,1,1);const voxel=new Map(),instanceMeta=new Map(),meshGroups={};let worldBounds=38,waterY=3;
const k3=(x,y,z)=>`${x},${y},${z}`;const parse=k=>k.split(',').map(Number);
function addBlock(x,y,z,type,save=false){x=Math.round(x);y=Math.round(y);z=Math.round(z);if(y<0||y>32)return;voxel.set(k3(x,y,z),type);if(save)edited.set(k3(x,y,z),type)}
function removeBlock(x,y,z){const k=k3(x,y,z);voxel.delete(k);edited.set(k,null)}
function rand(x,z,s=1){let n=Math.sin(x*127.1+z*311.7+s*74.7)*43758.5453;return n-Math.floor(n)}
function terrainHeight(x,z){const broad=Math.sin(x*.085+1.1)*2.1+Math.cos(z*.092-.5)*2.2+Math.sin((x+z)*.045)*2;const ridge=Math.max(0,Math.sin(x*.034+z*.051))*Math.max(0,Math.cos(z*.045-x*.03))*5.2;return Math.floor(5+broad+ridge)}
function biomeAt(x,z){const n=Math.sin(x*.07)*Math.cos(z*.09);if(n<-.45)return 'PINEWOOD';if(n>.57)return 'HIGHLANDS';if(terrainHeight(x,z)<waterY+1)return 'RIVERBANK';return 'SUNLIT MEADOW'}
const seedKey='wildbound-save-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(seedKey)||'{}')}catch{}
const edited=new Map(Object.entries(saved.edits||{}));let inventory=Object.assign({grass:0,dirt:0,stone:0,wood:0,leaves:0,plank:0,brick:0,sand:0,berry:3,workbench:0},saved.inventory||{});
function generate(){
 for(let x=-worldBounds;x<worldBounds;x++)for(let z=-worldBounds;z<worldBounds;z++){
  const h=terrainHeight(x,z),shore=h<=waterY+1;for(let y=0;y<=h;y++){
   let type=y===0?'bedrock':y===h?(shore?'sand':'grass'):y>h-3?'dirt':'stone';
   // Simple winding cave pockets in the deeper hillside.
   const cave=y>1&&y<h-2&&Math.sin(x*.29+y*.4)*Math.cos(z*.28-y*.22)>.88;
   if(!cave)addBlock(x,y,z,type);
  }
  if(!shore&&h>waterY+1&&rand(x,z)>.94){
   const pine=biomeAt(x,z)==='PINEWOOD',trunk=3+Math.floor(rand(x,z,2)*2);
   for(let y=1;y<=trunk;y++)addBlock(x,h+y,z,'wood');
   for(let dy=0;dy<3;dy++)for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)if(Math.abs(dx)+Math.abs(dz)<4&&rand(x+dx,z+dz,dy)>.08)addBlock(x+dx,h+trunk-1+dy,z+dz,'leaves');
   if(pine)for(let y=trunk-1;y<trunk+3;y++)for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)if(Math.abs(dx)+Math.abs(dz)<=(y<trunk+1?2:1))addBlock(x+dx,h+y,z+dz,'leaves');
  } else if(!shore&&rand(x,z,9)>.986){const n=1+Math.floor(rand(x,z,8)*3);for(let dx=-n;dx<=n;dx++)for(let dz=-n;dz<=n;dz++)if(rand(x+dx,z+dz,3)>.12)addBlock(x+dx,h+1,z+dz,'stone')}
 }
 // Restore player-made edits over the generated seed.
 for(const [key,type] of edited){if(type===null)voxel.delete(key);else voxel.set(key,type)}
 if(saved.creatures&&saved.creatures.length){creatureSpots.push(...saved.creatures)}
 rebuildWorld();
}
function rebuildWorld(){
 for(const group of Object.values(meshGroups))scene.remove(group);for(const k of Object.keys(meshGroups))delete meshGroups[k];instanceMeta.clear();
 const lists={};for(const [key,type] of voxel){(lists[type]??=[]).push(parse(key))}
 for(const [type,coords]of Object.entries(lists)){const mesh=new THREE.InstancedMesh(blockGeo,materials[type]||materials.stone,coords.length);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.blockType=type;const dummy=new THREE.Object3D();coords.forEach((p,i)=>{dummy.position.set(p[0],p[1]+.5,p[2]);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);instanceMeta.set(`${type}:${i}`,p)});mesh.instanceMatrix.needsUpdate=true;scene.add(mesh);meshGroups[type]=mesh}
}
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:0x456f75,roughness:.22,metalness:.15,transparent:true,opacity:.86}));ground.rotation.x=-Math.PI/2;ground.position.y=waterY+.06;ground.receiveShadow=true;scene.add(ground);
const waterSurface=new THREE.Mesh(new THREE.PlaneGeometry(200,200,1,1),new THREE.MeshPhongMaterial({color:0x5799a0,transparent:true,opacity:.38,shininess:110,specular:0xa8e5e3,side:THREE.DoubleSide}));waterSurface.rotation.x=-Math.PI/2;waterSurface.position.y=waterY+.08;scene.add(waterSurface);
const sunBall=new THREE.Mesh(new THREE.SphereGeometry(2.2,20,16),new THREE.MeshBasicMaterial({color:0xffe6a8}));scene.add(sunBall);
// Clouds are soft, layered silhouettes that drift across the upper sky.
const clouds=[];const cloudMat=new THREE.MeshStandardMaterial({color:0xf2f2e7,roughness:1,transparent:true,opacity:.76});
for(let i=0;i<14;i++){const cloud=new THREE.Group();const cx=(rand(i,2)-.5)*130,cz=(rand(i,3)-.5)*130;for(let j=0;j<5;j++){const puff=new THREE.Mesh(new THREE.BoxGeometry(4+rand(i,j)*5,1.2+rand(j,i)*1.3,3+rand(j,4)*3),cloudMat);puff.position.set(j*2.7-5,rand(j,i)*.6,Math.sin(j)*1.3);cloud.add(puff)}cloud.position.set(cx,24+rand(i,4)*13,cz);scene.add(cloud);clouds.push(cloud)}

