const clouds=[];const cloudMat=new THREE.MeshStandardMaterial({color:0xf2f2e7,roughness:1,transparent:true,opacity:.76});
for(let i=0;i<14;i++){const cloud=new THREE.Group();const cx=(rand(i,2)-.5)*130,cz=(rand(i,3)-.5)*130;for(let j=0;j<5;j++){const puff=new THREE.Mesh(new THREE.BoxGeometry(4+rand(i,j)*5,1.2+rand(j,i)*1.3,3+rand(j,4)*3),cloudMat);puff.position.set(j*2.7-5,rand(j,i)*.6,Math.sin(j)*1.3);cloud.add(puff)}cloud.position.set(cx,24+rand(i,4)*13,cz);scene.add(cloud);clouds.push(cloud)}

let player={x:Number(saved.player?.x)||0,y:terrainHeight(0,0)+.03,z:Number(saved.player?.z)||0,yaw:0,pitch:0,vy:0,health:saved.health??100,food:saved.food??100,stamina:100};
let cameraThird=false,started=false,paused=false,dayTime=saved.dayTime??.25,selected=0,target=null,hotbarCounts=[15,8,6,0,0,0,0,0];
let keys={},joystick={x:0,y:0},jumping=false,lastTime=performance.now(),damageClock=0,toastClock=0;
const raycaster=new THREE.Raycaster();raycaster.far=6;const center=new THREE.Vector2(0,0);
const creatures=[];const creatureSpots=saved.creatures||[];
function makeCritter(x,z){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.BoxGeometry(.8,.65,.95),new THREE.MeshStandardMaterial({color:0x79a884,roughness:.72}));body.position.y=.57;body.castShadow=true;g.add(body);const head=new THREE.Mesh(new THREE.BoxGeometry(.57,.53,.58),new THREE.MeshStandardMaterial({color:0x8dbd93,roughness:.7}));head.position.set(0,.95,.28);head.castShadow=true;g.add(head);for(const x0 of [-.17,.17]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.055,8,6),new THREE.MeshBasicMaterial({color:0x17221c}));eye.position.set(x0,1.02,.58);g.add(eye)}g.position.set(x,terrainHeight(Math.round(x),Math.round(z))+1,z);g.userData={homeX:x,homeZ:z,phase:rand(x,z)*8,hp:3};scene.add(g);creatures.push(g)}
for(let i=0;i<8;i++){let x=Math.round((rand(i,14)-.5)*58),z=Math.round((rand(i,19)-.5)*58);if(Math.hypot(x,z)>9&&terrainHeight(x,z)>waterY+1)makeCritter(x,z)}
function getGround(x,z){return terrainHeight(Math.round(x),Math.round(z))}
const avatar=new THREE.Group();const avatarMat=new THREE.MeshStandardMaterial({color:0x334a3e,roughness:.8});const avatarSkin=new THREE.MeshStandardMaterial({color:0xd9ae85,roughness:.75});
const torso=new THREE.Mesh(new THREE.BoxGeometry(.55,.82,.32),avatarMat);torso.position.y=1.08;avatar.add(torso);const head=new THREE.Mesh(new THREE.BoxGeometry(.36,.38,.36),avatarSkin);head.position.y=1.7;avatar.add(head);const legs=[];for(const x of [-.15,.15]){const l=new THREE.Mesh(new THREE.BoxGeometry(.2,.62,.22),new THREE.MeshStandardMaterial({color:0x493f35}));l.position.set(x,.36,0);avatar.add(l);legs.push(l)}avatar.traverse(o=>{if(o.isMesh)o.castShadow=true});scene.add(avatar);
function addToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastClock);toastClock=setTimeout(()=>el.classList.remove('show'),1700)}
function saveGame(notify=true){const data={player:{x:player.x,y:player.y,z:player.z},health:player.health,food:player.food,dayTime,inventory,edits:Object.fromEntries(edited),creatures:creatures.map(c=>[c.position.x,c.position.z])};localStorage.setItem(seedKey,JSON.stringify(data));if(notify)addToast('World saved to this device')}
function refreshHotbar(){const bar=document.querySelector('#hotbar');bar.innerHTML='';palette.forEach(([type,name,icon],i)=>{const count=inventory[type]||0;const el=document.createElement('div');el.className='slot'+(i===selected?' active':'');el.innerHTML=`<span class="slot-num">${i+1}</span><span class="block-icon">${icon}</span><span class="slot-name">${name.toUpperCase()}</span><span class="slot-count">${count||''}</span>`;el.onclick=()=>{selected=i;refreshHotbar()};bar.append(el)})}
function updateInventory(){const grid=document.querySelector('#inventoryGrid');const names={grass:'Grass block',dirt:'Packed earth',stone:'Stone',wood:'Timber',leaves:'Foliage',plank:'Wood planks',brick:'Clay brick',sand:'River sand',berry:'Wild berries',workbench:'Workbenches'};grid.innerHTML='';for(const [type,name,icon]of [...palette,['berry','Berries','●'],['workbench','Workbench','⌂']]){const n=inventory[type]||0;const el=document.createElement('div');el.className='inventory-item';el.innerHTML=`<span class="item-emoji">${icon}</span><span><b>${n}</b><small>${names[type]}</small></span>`;grid.append(el)}
 const recipes=[['Wood planks','plank',4,{wood:1}],['Stone bricks','brick',2,{stone:3}],['Workbench','workbench',1,{wood:4,stone:2}],['Wooden pick','pick',1,{wood:3,stone:2}]];const box=document.querySelector('#recipes');box.innerHTML='';for(const [name,out,amount,cost]of recipes){const ok=Object.entries(cost).every(([k,n])=>(inventory[k]||0)>=n);const req=Object.entries(cost).map(([k,n])=>`${n} ${k}`).join(' + ');const row=document.createElement('div');row.className='recipe';row.innerHTML=`<div><b>${name}</b><small>${req} → ${amount} ${out==='pick'?'tool':out}</small></div><button ${ok?'':'disabled'}>CRAFT</button>`;row.querySelector('button').onclick=()=>{if(!Object.entries(cost).every(([k,n])=>(inventory[k]||0)>=n))return;for(const[k,n]of Object.entries(cost))inventory[k]-=n;if(out==='pick')inventory.pick=1;else inventory[out]=(inventory[out]||0)+amount;updateInventory();refreshHotbar();addToast(`${name} crafted`);saveGame(false)};box.append(row)} }
function openInventory(){updateInventory();document.querySelector('#inventoryPanel').classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock()}
function closeInventory(){document.querySelector('#inventoryPanel').classList.add('hidden')}

